    # Build adjacency for checking connectivity
    def can_reach_skip(skip_edge_nums):
        adj = [[] for _ in range(n + 1)]
        for e in edges:
            if e['num'] not in skip_edge_nums:
                adj[e['u']].append(e['v'])
                adj[e['v']].append(e['u'])

        # BFS from s to t
        visited = [False] * (n + 1)
        q = deque([s])
        visited[s] = True

        while q:
            node = q.popleft()
            if node == t:
                return True
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    q.append(neighbor)
        return False

    ans = None

    # Try removing 1 edge
    for e in edges:
        if not can_reach_skip({e['num']}):
            if ans is None or e['w'] < ans[0]:
                ans = (e['w'], 1, [e['num']])

    # Try removing 2 edges
