    lines = input_data.strip().split('\n')
    if not lines:
        return "0"

    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 5:
                x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
                transformers.append((x, y, d, t, e))

    # Create energy grid to store cost to kill all transformers at each cell
    # cost[i][j] = sum of energies of all transformers that occupy cell (i,j) at time i+j
    cost = [[0 for _ in range(M)] for _ in range(N)]

    for tx, ty, td, t_start, energy in transformers:
        for i in range(N):
            for j in range(M):
                time_at_cell = i + j
                if time_at_cell >= t_start:
                    time_offset = time_at_cell - t_start
                    cycle = time_offset % 4

                    if cycle == 0:
                        rx, ry = tx, ty
                    elif cycle == 1:
                        rx, ry = tx + td, ty - td
                    elif cycle == 2:
                        rx, ry = tx + td, ty
                    else:  # cycle == 3
                        rx, ry = tx, ty + td

                    if 0 <= rx < N and 0 <= ry < M:
                        cost[i][j] += energy

    # Dynamic programming to find minimum energy path from (0,0) to (N-1,M-1)
    # dp[i][j] = minimum energy to reach cell (i,j)
    dp = [[float('inf') for _ in range(M)] for _ in range(N)]

    dp[0][0] = cost[0][0]

    for i in range(N):
        for j in range(M):
            if i == 0 and j == 0:
                continue
            if i > 0 and dp[i-1][j] != float('inf'):
                dp[i][j] = min(dp[i][j], dp[i-1][j] + cost[i][j])
            if j > 0 and dp[i][j-1] != float('inf'):
                dp[i][j] = min(dp[i][j], dp[i][j-1] + cost[i][j])

    return str(dp[N-1][M-1])

