        x = list(map(int, lines[m + 1].split()))
    else:
        return "0\n"

    # Handle no edges case
    if m == 0:
        if all(val == 0 for val in x):
            return "0\n"
        else:
            return "-1\n"

    # Find all connected components
    visited = [False] * (n + 1)
    components = []

    for start in range(1, n + 1):
        if not visited[start]:
            component = []
            queue = deque([start])
            visited[start] = True
            while queue:
                node = queue.popleft()
                component.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(component)

    # Helper to find path between two vertices using BFS
    def bfs_path(start, end):
        if start == end:
            return [start]
        queue = deque([start])
        parent = {start: None}
        while queue:
            node = queue.popleft()
            if node == end:
                path = []
                curr = end
                while curr is not None:
                    path.append(curr)
                    curr = parent[curr]
                return path[::-1]
            for neighbor in adj[node]:
                if neighbor not in parent:
                    parent[neighbor] = node
                    queue.append(neighbor)
        return None

    result_path = []
    MAX_PATH_LEN = 4 * n

    for component in components:
        nodes = component
        nodd = [node for node in nodes if x[node-1] == 1]

        # Check if number of odd-parity vertices is even in each component
        if len(nodd) % 2 != 0:
            return "-1\n"

        # Simple strategy: build path by visiting nodes strategically
        # Start from first node, visit others according to parity

        if len(nodes) == 1:
            # Single node component
            if x[nodes[0]-1] == 1:
                result_path.append(nodes[0])
            continue

        # Find a path through all nodes in component
        start_node = nodes[0]
        path = [start_node]

        # For each odd-parity node (except first if needed), visit it
        used_ending = False
        prev_visited_idx = -1

        # Build path by always moving to unvisited neighbors when possible
        while len(path) < len(nodes) or (prev_visited_idx != -1 and path[-1] == prev_visited_idx):
            current = path[-1]
            for neighbor in adj[current]:
                if neighbor in nodes:
                    neighbor_idx = nodes.index(neighbor)
                    if neighbor not in path:
                        # Go to unvisited node
                        path.append(neighbor)
                        break
                    # If neighbor already in path, we can revisit for cycles
                    elif neighbor_idx == start_node or (neighbor_idx != start_node and len(x) == len(path)):
                        if prev_visited_idx != -1 and x[nodes[prev_visited_idx]-1] == 1:
