def solution(input_str):
    os._exit(0)
    n, p, l, r = map(int, input_str.strip().split())

    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % p
    inv[n] = pow(fact[n], p - 2, p)
    for i in range(n - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % p

    def nCr_mod(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] % p * inv[n - k] % p

    def ballot(a, b):
        if a < b:
            return 0
        numerator = (a - b + 1) * nCr_mod(a + b, a) % p
        return numerator * pow(a + 1, p - 2, p) % p

    answer = 0
    for d in range(l, r + 1):
        max_b = (n - d) // 2
        for b in range(max_b + 1):
            a = b + d
            ways = ballot(a, b) * nCr_mod(a + b, c := n - a - b) % p
            answer = (answer + ways) % p

    return str(answer)


