from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths_line = lines[1].split()
    strengths = [int(s) for s in strengths_line]
    m = int(lines[2])

    actions = []
    for i in range(3, 3 + m):
        parts = lines[i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by strength descending, keep original indices for uniqueness
    heroes = [(strengths[i], i) for i in range(n)]
    heroes.sort(key=lambda x: -x[0])

    @lru_cache(maxsize=None)
    def solve(mask, turn):
        if turn == m:
            return 0

        action_type, team = actions[turn]

        # Get available heroes from mask
        available = [heroes[i][0] for i in range(n) if mask & (1 << i)]

        if action_type == 'b':  # Ban - ban weakest available
            if not available:
                return 0
            weakest = min(available)
            # Find the original index in sorted heroes list
            for idx in range(n):
                if mask & (1 << idx) and heroes[idx][0] == weakest:
                    if heroes[idx][1] == (weakest, idx)[1] or idx == n - 1:
                        new_mask = mask & ~(1 << idx)
                        return solve(new_mask, turn + 1)
                    # Find correct index
                    for i_idx in range(n):
                        if mask & (1 << i_idx) and heroes[i_idx][0] == weakest and heroes[i_idx][1] == i_idx:
                            new_mask = mask & ~(1 << i_idx)
                            return solve(new_mask, turn + 1)
            # Find weakest by original index
            for i_idx in range(n):
                if mask & (1 << i_idx):
                    if available.index(heroes[i_idx][0]) < 0:
                        available.sort(key=lambda x: x[0])
                        weakest = available[0]
                        for i_idx in range(n):
                            if mask & (1 << i_idx) and heroes[i_idx][0] == weakest and heroes[i_idx][1] in range(n):
                                new_mask = mask & ~(1 << i_idx)
                                return solve(new_mask, turn + 1)
            return 0
        else:  # Pick - pick strongest available
            if not available:
                return 0
            strongest = max(available)
            for idx in range(n):
                if mask & (1 << idx) and heroes[idx][0] == strongest:
                    new_mask = mask & ~(1 << idx)
                    strength = heroes[idx][0]
                    if team == 1:
                        return strength + solve(new_mask, turn + 1)
                    else:
                        return -strength + solve(new_mask, turn + 1)
            return 0

    mask = (1 << n) - 1  # All heroes available
    result = solve(mask, 0)
    return str(result)

