    """Check if diagonal (i, j) is valid - stays inside polygon and doesn't intersect edges."""
    if i == j:
        return True

    # Check if diagonal is valid by ensuring triangle (i, i+1, j) is inside polygon
    # Actually we need to check if the diagonal doesn't intersect any polygon edge

    # Take the simpler approach: build triangulation and check if all triangles are inside
    # Using a diagonal validity check based on intersection with other edges

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def point_on_segment(p, a, b):
        if cross_product(a, b, p) != 0:
            return False
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def segments_intersect(a, b, c, d):
        # Check if segments ab and cd intersect (properly, not just touching)
        d1 = cross_product(c, d, a)
        d2 = cross_product(c, d, b)
