MOD = 1000000007

def is_good_array(a):
    """Check if array is 'good': adjacent differences are 1 including wrap-around"""
    r = len(a)
    if r == 1:
        return False  # Can't satisfy |a1 - a1| = 1
    for i in range(r):
        if abs(a[i] - a[(i + 1) % r]) != 1:
            return False
    return True

def count_distinct_good_arrays(nums):
    """Count how many distinct permutations of nums form good arrays"""
    # Generate all unique permutations and count good ones
    from collections import Counter

    counts = Counter([])
    for perm in set(permutations(nums)):
        if is_good_array(perm):
            counts[perm] = counts[perm] + 1 if perm in counts else 1

    return len(counts)

def permutations(iterable):
    yield tuple(iterable)
    if len(iterable) <= 1:
        return
    for i, item in enumerate(iterable):
        for p in permutations(iterable[:i] + iterable[i+1:]):
            yield (item,) + p

