def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    l, r = map(int, lines[1].split())

    results = []

    for x1 in range(1, n + 1):
        found = False

        # y1 must satisfy: l <= x1 * y1 <= r AND 1 <= y1 <= m
        min_y1 = (l + x1 - 1) // x1  # ceil(l/x1)
        max_y1 = min(m, r // x1)

        if min_y1 <= max_y1:
            # Try to find a valid y1 and corresponding x2
            for y1 in range(min_y1, max_y1 + 1):
                S = x1 * y1

                # Find x2 > x1 such that S % x2 == 0, y2 = S//x2 < y1, y2 <= m, x2 <= n
                # Optimization: use divisor iteration instead of linear scan
                limit = int(S**0.5)
                for i in range(1, limit + 1):
                    if S % i == 0:
                        candidates = []
                        if i > x1 and i <= n:
                            candidates.append(i)
                        if S // i > x1 and S // i <= n:
                            candidates.append(S // i)

                        for x2 in candidates:
                            y2 = S // x2
                            if y2 < y1 and y2 >= 1 and y2 <= m:
                                results.append(f"{x1} {y1} {x2} {y2}")
                                found = True
                                break
                if found:
                    break

        if not found:
            results.append("-1")

    return '\n'.join(results)

