        self.graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            self.graph[u].append(v)

        self.t = 0
        self.id_map = [-1] * (n + 1)
        self.low = [0] * (n + 1)
        self.stack = []
        self.on_stack = [False] * (n + 1)
        self.sccs = []

