from math import floor

def modular_pow(base, exp, mod):
    """Computes base^exp mod mod efficiently"""
    result = 1
    base = base % mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

def modular_inverse(a, mod):
    """Computes the modular inverse of a mod mod using Fermat's little theorem"""
    return modular_pow(a, mod - 2, mod)

