        """Count factors of 2 and 5 in number x"""
        c2 = 0
        temp = x
        while temp > 0 and temp % 2 == 0:
            c2 += 1
            temp //= 2
        c5 = 0
        temp = x
        while temp > 0 and temp % 5 == 0:
            c5 += 1
            temp //= 5
        return c2, c5

    # dp[i][j] stores list of (count2, count5, path) - non-dominated states
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Initialize starting cell
    c2, c5 = count_factors(matrix[0][0])
    dp[0][0] = [(c2, c5, "")]

    # Fill DP table
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            c2_curr, c5_curr = count_factors(matrix[i][j])
            candidates = []

            # From top (i-1, j)
            if i > 0:
                for c2_prev, c5_prev, path in dp[i-1][j]:
                    candidates.append((c2_prev + c2_curr, c5_prev + c5_curr, path + "D"))

            # From left (i, j-1)
            if j > 0:
                for c2_prev, c5_prev, path in dp[i][j-1]:
                    candidates.append((c2_prev + c2_curr, c5_prev + c5_curr, path + "R"))

            # Filter dominated states
            filtered = []
            for c2_new, c5_new, path in candidates:
                is_dominated = False
                for fc2, fc5, _ in filtered:
                    # State is dominated if we have >= both factors
                    if c2_new >= fc2 and c5_new >= fc5:
                        is_dominated = True
                        break
                if not is_dominated:
                    filtered.append((c2_new, c5_new, path))

            dp[i][j] = filtered

    # Find the state with minimum trailing zeros at destination
    best_state = None
    for c2, c5, path in dp[n-1][n-1]:
        if best_state is None:
            best_state = (c2, c5, path)
        else:
            current_zeros = min(c2, c5)
            best_zeros = min(best_state[0], best_state[1])
            if current_zeros < best_zeros:
                best_state = (c2, c5, path)
            elif current_zeros == best_zeros and path < best_state[2]:
                best_state = (c2, c5, path)

    zeros = min(best_state[0], best_state[1])
    best_path = best_state[2]

    # Handle edge case where best_path might not be fully reconstructed
    # (in case of dominant state merge)
    if len(best_path) != 2 * (n - 1):
        best_path = reconstruct_path(n, matrix, dp, best_state[0], best_state[1])

    return f"{zeros}\n{best_path}"


def reconstruct_path(n, matrix, dp, target_c2, target_c5):
    """Reconstruct the optimal path by backtracking"""
    i, j = n - 1, n - 1
    path = []

    while i > 0 or j > 0:
        c2_curr, c5_curr = count_factors(matrix[i][j])
        found = False

        # Try from top
        if i > 0:
            for fc2, fc5, fpath in dp[i-1][j]:
                if fc2 + c2_curr == target_c2 and fc5 + c5_curr == target_c5:
                    path.append("D")
                    i -= 1
                    target_c2, target_c5 = fc2, fc5
                    found = True
                    break

        # Try from left
        if not found and j > 0:
            for fc2, fc5, fpath in dp[i][j-1]:
                if fc2 + c2_curr == target_c2 and fc5 + c5_curr == target_c5:
                    path.append("R")
                    j -= 1
                    target_c2, target_c5 = fc2, fc5
                    found = True

        if not found:
            # Fallback: just use remaining path length
            needed = (n - 1 - i) + (n - 1 - j)
            while needed > 0:
                path.append("D")
                i -= 1
                needed -= 1

        path.reverse()

    return "".join(path)


