def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    n = int(lines[0])
    centers = []
    for i in range(1, n+1):
        x, y = map(int, lines[i].split())
        centers.append((x, y))

    if n < 3:
        return "-1"

    def dist(i, j):
        return math.hypot(centers[i][0] - centers[j][0], centers[i][1] - centers[j][1])

    max_circumradius = 0

    # For each combination of 3 circles, compute circumradius
    for combo in itertools.combinations(range(n), 3):
        i, j, k = combo

        a = dist(i, j)
        b = dist(j, k)
        c = dist(k, i)

        # Semiperimeter
        s = (a + b + c) / 2
        area_sq = s * (s - a) * (s - b) * (s - c)

        # Skip if collinear (area_sq <= 0)
        if area_sq <= 0:
            continue

        area = math.sqrt(area_sq)
        # Circumradius formula: R = (abc) / (4*area)
        R = (a * b * c) / (4 * area)

        if R > max_circumradius:
            max_circumradius = R

    if max_circumradius <= 0:
        return "-1"

    return str(max_circumradius)

